use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

pub struct StatsCommand;

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let stats = project_stats(&entries);

        for (project, duration) in &stats {
            println!(
                "{}  {}",
                utilities::format_duration_compact(*duration),
                project
            );
        }
        let total = stats.iter().map(|(_, duration)| duration).sum();
        println!("{}  Total", utilities::format_duration_compact(total));

        Ok(())
    }
}

fn project_stats(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut durations = HashMap::<String, i64>::new();
    for entry in entries.iter().filter(|entry| entry.duration >= 0) {
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *durations.entry(project).or_default() += entry.duration;
    }

    let mut stats: Vec<_> = durations.into_iter().collect();
    stats.sort_by(|(left_name, left_duration), (right_name, right_duration)| {
        right_duration
            .cmp(left_duration)
            .then_with(|| left_name.cmp(right_name))
    });
    stats
}

